<div class="card"><h1>Listing Templates</h1><form method="post"><input name="title" placeholder="Title" required><textarea name="description" placeholder="Description"></textarea><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><select name="item_condition"><option value="good">Good</option><option value="new">New</option><option value="like_new">Like New</option><option value="fair">Fair</option></select><input type="number" step="0.01" name="starting_price" placeholder="Starting price"><button>Save Template</button></form></div><div class="card"><table><tr><th>Title</th><th>Category</th><th>Price</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['category_name']) ?></td><td><?= e($r['starting_price']) ?></td></tr><?php endforeach; ?></table></div>
